$ErrorActionPreference = 'Stop'
$patchPath = (Resolve-Path -LiteralPath 'ExtraFeatures/Patches/Assets/GUI/XAMLResources/HUD_Buildings.xaml').Path
$patchText = [IO.File]::ReadAllText($patchPath)
$operation = [regex]::Match($patchText, '(?s)  <Operation Type="Add" XPath="//n:Grid\[@Name=''ShowGate''\]">.*?</Operation>').Value
if (-not $operation) { throw 'Gate button operation not found.' }
if ($patchText.Contains('ExtraFeaturesDrawbridgeAutomationButtonHost')) { throw 'Bridge UI already exists.' }
$bridge = $operation.Replace('ShowGate', 'ShowDrawbridge').Replace('ExtraFeaturesGatehouseAutomationButton', 'ExtraFeaturesDrawbridgeAutomationButton')
$patched = $patchText.Replace($operation, $operation + "`r`n" + $bridge)
[IO.File]::WriteAllText($patchPath, $patched, [Text.UTF8Encoding]::new($false))
if ([IO.File]::ReadAllText($patchPath) -cne $patched) { throw 'XAML verification failed.' }
$translations = @'
{"en-US":["Gatehouses and drawbridges","Automatic drawbridge control is enabled. Click to accept only direct commands to this drawbridge.","Manual-only drawbridge control is enabled. Gatehouse commands are ignored. Click to restore automatic control through the connected gatehouse."],"de-DE":["Torhäuser und Zugbrücken","Die automatische Zugbrückensteuerung ist aktiv. Klicken, um nur noch direkte Befehle an diese Zugbrücke anzunehmen.","Die Zugbrücke wird nur manuell gesteuert. Torhausbefehle werden ignoriert. Klicken, um die automatische Steuerung durch das verbundene Torhaus wieder einzuschalten."],"fr-FR":["Corps de garde et ponts-levis","Le contrôle automatique du pont-levis est actif. Cliquez pour accepter uniquement les ordres directs à ce pont-levis.","Le pont-levis est en mode manuel. Les ordres du corps de garde sont ignorés. Cliquez pour rétablir le contrôle automatique par le corps de garde relié."],"es-ES":["Puertas y puentes levadizos","El control automático del puente levadizo está activo. Haz clic para aceptar solo órdenes directas a este puente.","El puente está en modo manual e ignora las órdenes de la puerta. Haz clic para restaurar el control automático desde la puerta conectada."],"it-IT":["Portinerie e ponti levatoi","Il controllo automatico del ponte levatoio è attivo. Fai clic per accettare solo ordini diretti a questo ponte.","Il ponte è in modalità manuale e ignora gli ordini della portineria. Fai clic per ripristinare il controllo automatico dalla portineria collegata."],"pt-BR":["Portões e pontes levadiças","O controle automático da ponte levadiça está ativo. Clique para aceitar apenas ordens diretas para esta ponte.","A ponte está em modo manual e ignora ordens do portão. Clique para restaurar o controle automático pelo portão conectado."],"nl-NL":["Poortgebouwen en ophaalbruggen","De ophaalbrug wordt automatisch bestuurd. Klik om alleen rechtstreekse bevelen aan deze brug toe te staan.","De ophaalbrug wordt alleen handmatig bestuurd en negeert poortbevelen. Klik om automatische besturing via het verbonden poortgebouw te herstellen."],"sv-SE":["Porthus och vindbryggor","Automatisk styrning av vindbryggan är aktiv. Klicka för att endast tillåta direkta order till denna vindbrygga.","Vindbryggan styrs manuellt och ignorerar order från porthuset. Klicka för att återställa automatisk styrning via det anslutna porthuset."],"pl-PL":["Bramy i mosty zwodzone","Automatyczne sterowanie mostem zwodzonym jest włączone. Kliknij, aby przyjmować tylko bezpośrednie rozkazy dla tego mostu.","Most jest sterowany ręcznie i ignoruje rozkazy bramy. Kliknij, aby przywrócić automatyczne sterowanie przez połączoną bramę."],"cs-CZ":["Brány a padací mosty","Automatické ovládání padacího mostu je zapnuté. Kliknutím povolíte pouze přímé příkazy tomuto mostu.","Most je ovládán ručně a ignoruje příkazy brány. Kliknutím obnovíte automatické ovládání prostřednictvím připojené brány."],"hu-HU":["Kapuházak és felvonóhidak","A felvonóhíd automatikus vezérlése aktív. Kattints, hogy csak a hídnak közvetlenül kiadott parancsokat fogadja el.","A híd kézi vezérlésű, és figyelmen kívül hagyja a kapuház parancsait. Kattints a kapcsolódó kapuház általi automatikus vezérlés visszaállításához."],"ru-RU":["Воротные башни и подъёмные мосты","Автоматическое управление мостом включено. Нажмите, чтобы мост принимал только прямые команды.","Мост управляется вручную и игнорирует команды воротной башни. Нажмите, чтобы восстановить автоматическое управление через связанную башню."],"uk-UA":["Надбрамні вежі та підйомні мости","Автоматичне керування мостом увімкнено. Натисніть, щоб міст приймав лише прямі команди.","Міст керується вручну та ігнорує команди надбрамної вежі. Натисніть, щоб відновити автоматичне керування через з'єднану вежу."],"ja-JP":["門楼と跳ね橋","跳ね橋の自動制御が有効です。クリックすると、この橋への直接の指示のみを受け付けます。","跳ね橋は手動制御で、門楼からの指示を無視します。クリックすると、接続された門楼による自動制御に戻ります。"],"ko-KR":["성문과 도개교","도개교 자동 제어가 켜져 있습니다. 클릭하면 이 도개교에 직접 내린 명령만 받습니다.","도개교가 수동 제어 중이며 성문의 명령을 무시합니다. 클릭하면 연결된 성문을 통한 자동 제어로 돌아갑니다."],"zh-CN":["门楼与吊桥","吊桥自动控制已启用。点击后，仅接受直接向此吊桥下达的命令。","吊桥处于手动模式，忽略门楼命令。点击恢复由相连门楼进行的自动控制。"],"zh-HK":["門樓與吊橋","吊橋自動控制已啟用。點擊後，僅接受直接向此吊橋下達的命令。","吊橋處於手動模式，忽略門樓命令。點擊恢復由相連門樓進行的自動控制。"],"tr-TR":["Kapı binaları ve asma köprüler","Asma köprünün otomatik kontrolü açık. Yalnızca bu köprüye doğrudan verilen emirleri kabul etmek için tıklayın.","Köprü elle kontrol edilir ve kapı emirlerini yok sayar. Bağlı kapı üzerinden otomatik kontrolü geri açmak için tıklayın."],"el-GR":["Πύλες και κινητές γέφυρες","Ο αυτόματος έλεγχος της γέφυρας είναι ενεργός. Κάντε κλικ για να δέχεται μόνο άμεσες εντολές προς αυτήν.","Η γέφυρα ελέγχεται χειροκίνητα και αγνοεί τις εντολές της πύλης. Κάντε κλικ για επαναφορά του αυτόματου ελέγχου μέσω της συνδεδεμένης πύλης."],"ar":["بوابات وجسور متحركة","التحكم التلقائي بالجسر مفعّل. انقر لقبول الأوامر المباشرة لهذا الجسر فقط.","الجسر في الوضع اليدوي ويتجاهل أوامر البوابة. انقر لاستعادة التحكم التلقائي عبر البوابة المتصلة."],"th-TH":["ป้อมประตูและสะพานชัก","เปิดการควบคุมสะพานชักอัตโนมัติอยู่ คลิกเพื่อรับเฉพาะคำสั่งที่สั่งสะพานนี้โดยตรง","สะพานชักอยู่ในโหมดควบคุมด้วยตนเองและไม่รับคำสั่งจากป้อมประตู คลิกเพื่อกลับไปควบคุมอัตโนมัติผ่านป้อมประตูที่เชื่อมต่อ"]}
'@ | ConvertFrom-Json
foreach ($entry in $translations.PSObject.Properties) {
 $target = (Resolve-Path -LiteralPath ('ExtraFeatures/Locales/' + $entry.Name + '.txt')).Path
 $value = [IO.File]::ReadAllText($target)
 $value = [regex]::Replace($value, '(?m)^SomeSettings.GatehousesTitle=[^\r\n]*', ('SomeSettings.GatehousesTitle=' + $entry.Value[0]))
 $value = $value.TrimEnd([char]13,[char]10) + "`r`nSomeSettings.DrawbridgeAutomaticEnabledTooltip=" + $entry.Value[1] + "`r`nSomeSettings.DrawbridgeManualOnlyTooltip=" + $entry.Value[2] + "`r`n"
 [IO.File]::WriteAllText($target, $value, [Text.UTF8Encoding]::new($false))
 if ([IO.File]::ReadAllText($target) -cne $value) { throw 'Locale verification failed.' }
}
Write-Output 'Added drawbridge HUD operation and 21 localized tooltip pairs.'

